<template><view class="page">
  <view class="summary"><view><b>32</b><span>全部台位</span></view><view><b class="green">{{free}}</b><span>空闲</span></view><view><b class="yellow">{{reserved}}</b><span>已预订</span></view><view><b class="blue">{{serving}}</b><span>使用中</span></view></view>
  <view class="filters"><button v-for="item in filters" :key="item" :class="{active:filter===item}" @click="filter=item">{{item}}</button></view>
  <view class="floor">
    <view class="stage">DJ台 / 舞台</view>
    <view class="zone vip">VIP 区</view><view class="map-row"><button v-for="t in visibleTables.filter(t=>t.zone==='VIP')" :key="t.id" :class="['table',t.status]" @click="select(t)"><b>{{t.id}}</b><span>{{stateName[t.status]}}</span></button></view>
    <view class="dance">舞池区域</view>
    <view class="zone">卡座区</view><view class="map-row"><button v-for="t in visibleTables.filter(t=>t.zone==='卡座')" :key="t.id" :class="['table',t.status]" @click="select(t)"><b>{{t.id}}</b><span>{{stateName[t.status]}}</span></button></view>
    <view class="bar">吧台 · BAR</view>
  </view>
  <view class="legend"><span><i class="free"></i>空闲</span><span><i class="reserved"></i>已预订</span><span><i class="serving"></i>消费中</span><span><i class="cleaning"></i>待清台</span></view>
  <view v-if="selected" class="mask" @click="selected=null"><view class="sheet" @click.stop><view class="handle"></view><view class="sheet-head"><view><text>台位 {{selected.id}}</text><span>{{selected.zone}} · 建议 {{selected.capacity}} 人</span></view><b :class="selected.status">{{stateName[selected.status]}}</b></view><template v-if="selected.order"><view class="customer"><view><span>客户</span><b>{{selected.order.customerName}}</b></view><view><span>到店时间</span><b>{{selected.order.arrivalTime}}</b></view><view><span>归属销售</span><b>{{selected.order.salesName}}</b></view></view><button class="primary" @click="goOrder">查看并操作订单</button></template><button v-else class="primary" @click="create">为此台创建预订</button></view></view>
</view></template>
<script setup lang="ts">
import{computed,ref}from'vue';import{getOrders,type ClubOrder,type OrderStatus}from'../../services/orders'
type TableState='free'|'reserved'|'arrived'|'serving'|'cleaning';interface ClubTable{id:string;zone:string;capacity:number;status:TableState;order?:ClubOrder}
const orders=getOrders(),ids=['V01','V02','V03','V05','V06','V08','A01','A02','A03','A05','A06','A08','B01','B02','B03','B05','B06','B08'];const tables=ref<ClubTable[]>(ids.map((id,i)=>{const order=orders.find(o=>o.tableId===id);return{id,zone:id.startsWith('V')?'VIP':'卡座',capacity:id.startsWith('V')?10:6,status:(order?.status as TableState)||(['free','free','cleaning'][i%3] as TableState),order}}))
const filters=['全部','空闲','已预订','使用中'],filter=ref('全部'),selected=ref<ClubTable|null>(null),stateName:Record<TableState,string>={free:'空闲',reserved:'已预订',arrived:'已到店',serving:'消费中',cleaning:'待清台'}
const visibleTables=computed(()=>tables.value.filter(t=>filter.value==='全部'||(filter.value==='空闲'&&t.status==='free')||(filter.value==='已预订'&&t.status==='reserved')||(filter.value==='使用中'&&['arrived','serving'].includes(t.status)))),free=computed(()=>tables.value.filter(t=>t.status==='free').length),reserved=computed(()=>tables.value.filter(t=>t.status==='reserved').length),serving=computed(()=>tables.value.filter(t=>['arrived','serving'].includes(t.status)).length)
const select=(t:ClubTable)=>selected.value=t,create=()=>uni.navigateTo({url:`/pages/booking/index?table=${selected.value?.id}`}),goOrder=()=>uni.navigateTo({url:'/pages/orders/index'})
</script>
