d{background:#e59c13}.legend i.serving{background:#3478f6}.legend i.cleaning{background:#999}.mask{position:fixed;inset:0;background:rgba(0,0,0,.35);display:flex;align-items:end;justify-content:center}.sheet{width:min(480px,100%);background:#fff;border-radius:17px 17px 0 0;padding:10px 18px 25px}.handle{width:32px;height:4px;background:#ddd;border-radius:4px;margin:0 auto 18px}.sheet-head{display:flex;justify-content:space-between;align-items:start}.sheet-head text{display:block;font-size:20px;font-weight:700}.sheet-head span{display:block;font-size:10px;color:#999;margin-top:5px}.sheet-head>b{font-size:10px;color:#07c160;background:#e8f8ed;padding:6px 9px;border-radius:14px}.customer{display:grid;grid-template-columns:repeat(3,1fr);background:#f7f7f7;border-radius:9px;padding:13px;margin-top:18px}.customer span,.customer b{display:block}.customer span{font-size:9px;color:#999}.customer b{font-size:11px;margin-top:5px}.primary{margin-top:18px;height:48px;background:#07c160;color:#fff;border-radius:7px;font-size:13px}
